 record['steps'].append({'at':m.now(),'stage':stage});p=out/'retirement.json';tmp=out/'retirement.tmp';tmp.write_text(json.dumps(record,indent=2)+'\n');os.replace(tmp,p);fd=os.open(p,os.O_RDONLY);os.fsync(fd);os.close(fd)
